<?php
namespace Database\Seeders;
use Illuminate\Database\Seeder; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Hash;
class DatabaseSeeder extends Seeder { public function run(): void {
    DB::table('companies')->insertOrIgnore(['id'=>1, 'name'=>'Platform', 'created_at'=>now(), 'updated_at'=>now()]);
    // Requirement: create the SuperAdmin using raw SQL. The password hash is generated by Laravel.
    $email = 'superadmin@example.com';
    if (! DB::table('users')->where('email', $email)->exists()) {
        DB::insert('INSERT INTO users (company_id, name, email, password, role, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?)', [null, 'Super Admin', $email, Hash::make('ChangeMe123!'), 'SuperAdmin', now(), now()]);
    }
} }
